using EnterpriseDocumentIntelligence.BuildingBlocks.Domain;
public sealed record AuditCommand(Guid TenantId,Guid? ActorId,string Action,string ResourceType,Guid? ResourceId,string Outcome,string? CorrelationId,string? MetadataJson);
public static class AuditRules{public static void Validate(AuditCommand c){if(c.TenantId==Guid.Empty)throw new ArgumentException("Tenant is required");if(string.IsNullOrWhiteSpace(c.Action))throw new ArgumentException("Action is required");if(string.IsNullOrWhiteSpace(c.ResourceType))throw new ArgumentException("ResourceType is required");if(string.IsNullOrWhiteSpace(c.Outcome))throw new ArgumentException("Outcome is required");}public static AuditEvent Create(AuditCommand c){Validate(c);return new AuditEvent(c.TenantId,c.ActorId,c.Action,c.ResourceType,c.ResourceId,c.Outcome,c.CorrelationId,c.MetadataJson);}}